"""A staged launch plan for Tink Town; planning ranges, not commitments."""
from html import escape
from phase_budgets import phase_budget, budget_assumptions

PHASES = [
 dict(label='Launch the service',size='No dedicated premises required',headline='Start with talent.<br>Put it to work.',intro='The first Tink Town can be a small team helping real clients. We can build relationships and earn revenue before taking on a large lease or a full workshop.',
 services=[('AI & agents','Improve workflows, automate repeated tasks and help staff use AI well.'),('Creative & print','Build websites, make videos and design marketing materials. Use compact professional printing where practical; outsource larger or specialist orders.'),('People & gatherings','Offer practical training, workshops, events and purpose coaching through online sessions, client visits and booked venues.')],
 place='Work from home, a small office or retail unit, client sites, or permitted shared spaces. Café meetings and bookable library rooms could support suitable conversations and workshops.',equipment='Existing computers and software first. Add a compact professional printer and finishing tools only when orders justify them. Use production partners for work beyond our equipment.',gate='Repeat paying clients, useful workshop demand and a clear case that a small permanent space would improve delivery.',
 note='One option to explore: separately agreed use of the school after hours—for example, 2:30–5:00 p.m. This would need the school operator’s approval, a separate part-time lease or use agreement, and arrangements that fit school activities.',cta='Bring an early project',url='contact.html?topic=projects'),
 dict(label='Open a small hub',size='Illustrative range: 1,500–3,000 sq ft',headline='Give the work<br>a place to gather.',intro='A modest public-facing home adds continuity: somewhere to meet clients, run workshops, collect orders and build a community around useful work.',
 services=[('A coffee corner','A small counter and seating area for conversation and client meetings, with the appropriate venue approvals.'),('A few useful machines','Professional print and finishing, desktop 3D printers, and selected tools chosen around the work customers actually request.'),('A working community','Shared worktables, a small maker-supply display, training sessions and regular gatherings. Continue the Phase 1 services.')],
 place='A smaller retail or commercial space with room for a coffee corner, worktables, clean printing, storage and a suitable separated machine area. The layout follows the equipment we choose.',equipment='Add capability one purchase or lease at a time. Start with frequently requested print and prototype work; keep outsourcing specialist fabrication.',gate='Reliable repeat orders, a workable operating margin and enough demand to support more equipment, specialist staff and a larger lease.',
 note='This is a working size range, not a fixed requirement. A well-arranged smaller space may work; selected machines and venue requirements determine the fit.',cta='Explore a first location',url='contact.html?topic=property'),
 dict(label='Build the full workshop',size='Working target: about 5,000–7,000 sq ft',headline='Scale the capability.<br>Keep the community.',intro='Grow toward the Tink Town we have been imagining: a café, creative workplace, maker shop and production workshop under one roof. Keep the earlier services and add capacity where it earns its place.',
 services=[('A fuller community hub','A café and kitchen, small performance stage, workshops, events and retail for robotics and making supplies.'),('Expanded production','Grow into laser cutting, CNC routing or milling, metal bending and other fabrication as the orders, skills and premises support them.'),('Bigger problems, one team','Connect design, AI, marketing, print and fabrication so clients can bring an idea and work toward a useful result in one place.')],
 place='About 5,000 sq ft could accommodate a selected, compact mix. Our detailed 6,700 sq ft example shows a fuller arrangement; a wider machine range or more public space may need more room.',equipment='The full equipment list is a direction for growth, not a day-one shopping list. Larger industrial machines—including a waterjet—remain separate decisions based on demand, installation costs and safe operation.',gate='Expand further only when customer demand and operating results support the next addition. A successful smaller Tink Town can remain smaller.',
 note='The earlier 7,500–9,000 sq ft preferred range allows more room for the fuller concept. It is not a condition for starting Tink Town.',cta='Explore the fuller space plan',url='investing.html#property')
]

def growth_plan():
 buttons=[];panels=[]
 for i,p in enumerate(PHASES):
  buttons.append(f'<button class="growth-tier tier-{i+1}" role="tab" id="growth-tab-{i}" aria-controls="growth-panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}"><span>PHASE {i+1:02}</span><strong>{p["label"]}</strong></button>')
  rows=''.join('<li><strong>'+escape(title)+'</strong><span>'+escape(body)+'</span></li>' for title,body in p['services'])
  note='<details class="growth-note"><summary>'+('Could we start at the school?' if i==0 else 'How to read this size estimate')+'</summary><p>'+escape(p['note'])+'</p></details>'
  panels.append(f'<section role="tabpanel" id="growth-panel-{i}" aria-labelledby="growth-tab-{i}" class="growth-panel"'+(' hidden' if i else '')+f'><span class="eyebrow">Phase {i+1:02} · {p["size"]}</span><h3>{p["headline"]}</h3><p class="growth-intro">{p["intro"]}</p><ul class="growth-services">{rows}</ul><div class="growth-practical"><div><h4>The space</h4><p>{p["place"]}</p></div><div><h4>The equipment</h4><p>{p["equipment"]}</p></div></div><div class="growth-gate"><span>{"Ready for the next phase when" if i<2 else "The rule for further growth"}</span><p>{p["gate"]}</p></div>{note}{phase_budget(i)}<a class="text-link" href="{p["url"]}">{p["cta"]}<span aria-hidden="true"> ↗</span></a></section>')
 return '''<section class="section growth-section" id="growth" data-growth-plan><div class="wrap"><div class="section-head"><div><span class="eyebrow">A practical path to opening</span><h2>Start small.<br>Build something big.</h2></div><p>We do not need every machine—or a 7,000-square-foot building—to begin. Start with useful services. Add space and equipment as the work grows.</p></div><div class="growth-layout"><div class="growth-visual"><span class="growth-direction">The ambition grows. The foundation stays.</span><div class="growth-pyramid" role="tablist" aria-label="Explore the three Tink Town phases" aria-orientation="vertical">'''+''.join(buttons)+'''</div><p class="growth-hint">Start at the base. Select a phase to explore.</p><div class="growth-principle"><strong>Demand first.<br>Investment follows.</strong><p>Buy, lease or outsource according to the work—not the wish list.</p></div><span class="growth-status">Proposed launch plan · timing follows demand</span></div><div class="growth-content">'''+''.join(panels)+'''</div></div>'''+budget_assumptions()+'''<p class="growth-footnote">These phases describe how we could launch and grow. Premises, services, equipment and opening dates are still being developed.</p></div></section>'''
